        "question": [
          "For the validated JSON, show costs by engine: {\"use_case_id\":\"BATCH_EXAMPLE\",\"use_case_name\":\"Batch example\",\"scenarios\":[\"EXPECTED\"],\"processing\":[{\"component_id\":\"B1\",\"name\":\"Batch\",\"workload_type\":\"SCHEDULED_BATCH\",\"runtime_hours_expected\":2,\"runs_per_month\":20}],\"_areas\":{\"processing\":\"INCLUDED\",\"sql\":\"NOT_APPLICABLE\",\"transfer\":\"NOT_APPLICABLE\",\"storage\":\"NOT_APPLICABLE\",\"model_endpoints\":\"NOT_APPLICABLE\",\"one_time_model_jobs\":\"NOT_APPLICABLE\"}}"
        ],
        "sql": [
          "SELECT li.scenario, li.engine, li.recurrence, SUM(CASE WHEN li.treatment = 'INCLUDED' THEN li.cost_usd END) AS priced_subtotal_usd, SUM(CASE WHEN li.treatment = 'PENDING' THEN 1 ELSE 0 END) AS pending_items FROM fevm_catalog_naren.lakemeter_onebook.dcp_calc_line_items(p_request => '{\"use_case_id\":\"BATCH_EXAMPLE\",\"use_case_name\":\"Batch example\",\"scenarios\":[\"EXPECTED\"],\"processing\":[{\"component_id\":\"B1\",\"name\":\"Batch\",\"workload_type\":\"SCHEDULED_BATCH\",\"runtime_hours_expected\":2,\"runs_per_month\":20}],\"_areas\":{\"processing\":\"INCLUDED\",\"sql\":\"NOT_APPLICABLE\",\"transfer\":\"NOT_APPLICABLE\",\"storage\":\"NOT_APPLICABLE\",\"model_endpoints\":\"NOT_APPLICABLE\",\"one_time_model_jobs\":\"NOT_APPLICABLE\"}}') AS li GROUP BY li.scenario, li.engine, li.recurrence ORDER BY li.scenario, li.engine, li.recurrence"
